CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,phone TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE roles(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE);
CREATE TABLE permissions(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE);
CREATE TABLE role_permissions(role_id INTEGER NOT NULL,permission_id INTEGER NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE staff(user_id INTEGER PRIMARY KEY,role_id INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT,image_url TEXT,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE collections(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT,image_url TEXT,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,sku TEXT UNIQUE,category_id INTEGER,collection_id INTEGER,gender TEXT,short_description TEXT,description TEXT,price INTEGER NOT NULL,sale_price INTEGER,stock INTEGER NOT NULL DEFAULT 0,low_stock_threshold INTEGER NOT NULL DEFAULT 3,weight REAL,fragrance_family TEXT,top_notes TEXT,heart_notes TEXT,base_notes TEXT,longevity TEXT,sillage TEXT,ingredients TEXT,tags TEXT,badges TEXT,featured INTEGER NOT NULL DEFAULT 0,best_seller INTEGER NOT NULL DEFAULT 0,new_arrival INTEGER NOT NULL DEFAULT 0,limited_edition INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,seo_title TEXT,seo_description TEXT,seo_keywords TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(collection_id) REFERENCES collections(id));
CREATE TABLE product_variants(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL,name TEXT NOT NULL,sku TEXT UNIQUE,price INTEGER NOT NULL,sale_price INTEGER,stock INTEGER NOT NULL DEFAULT 0,weight REAL,image_url TEXT,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE product_images(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL,public_id TEXT NOT NULL,secure_url TEXT NOT NULL,width INTEGER,height INTEGER,format TEXT,is_primary INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE media(id INTEGER PRIMARY KEY AUTOINCREMENT,public_id TEXT NOT NULL UNIQUE,secure_url TEXT NOT NULL,resource_type TEXT NOT NULL DEFAULT 'image',width INTEGER,height INTEGER,format TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE carts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,guest_token TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE cart_items(id INTEGER PRIMARY KEY AUTOINCREMENT,cart_id INTEGER NOT NULL,product_id INTEGER NOT NULL,variant_id INTEGER,quantity INTEGER NOT NULL CHECK(quantity>0),UNIQUE(cart_id,product_id,variant_id),FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE wishlists(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,guest_token TEXT UNIQUE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE wishlist_items(id INTEGER PRIMARY KEY AUTOINCREMENT,wishlist_id INTEGER NOT NULL,product_id INTEGER NOT NULL,UNIQUE(wishlist_id,product_id),FOREIGN KEY(wishlist_id) REFERENCES wishlists(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE addresses(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,label TEXT,name TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,city TEXT NOT NULL,postal_code TEXT,country TEXT NOT NULL DEFAULT 'Pakistan',is_default INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE orders(id INTEGER PRIMARY KEY AUTOINCREMENT,order_number TEXT NOT NULL UNIQUE,user_id INTEGER,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,city TEXT NOT NULL,postal_code TEXT,country TEXT NOT NULL DEFAULT 'Pakistan',subtotal INTEGER NOT NULL,discount INTEGER NOT NULL DEFAULT 0,delivery_fee INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL,payment_method TEXT NOT NULL,payment_status TEXT NOT NULL DEFAULT 'Pending',status TEXT NOT NULL DEFAULT 'Pending',tracking_number TEXT,courier TEXT,tracking_url TEXT,internal_notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE order_items(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,product_id INTEGER NOT NULL,variant_id INTEGER,name TEXT NOT NULL,sku TEXT,quantity INTEGER NOT NULL,unit_price INTEGER NOT NULL,line_total INTEGER NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE RESTRICT,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL UNIQUE,method TEXT NOT NULL,amount INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'Pending',reference TEXT,note TEXT,verified_by INTEGER,verified_at TEXT,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE RESTRICT,FOREIGN KEY(verified_by) REFERENCES users(id));
CREATE TABLE payment_receipts(id INTEGER PRIMARY KEY AUTOINCREMENT,payment_id INTEGER NOT NULL UNIQUE,public_id TEXT NOT NULL,secure_url TEXT NOT NULL,submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(payment_id) REFERENCES payments(id) ON DELETE RESTRICT);
CREATE TABLE reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL,user_id INTEGER NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),body TEXT NOT NULL,image_url TEXT,verified_purchase INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(product_id,user_id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE coupons(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL UNIQUE,type TEXT NOT NULL CHECK(type IN ('percentage','fixed')),value INTEGER NOT NULL,min_order INTEGER NOT NULL DEFAULT 0,max_discount INTEGER,usage_limit INTEGER,per_user_limit INTEGER,first_order INTEGER NOT NULL DEFAULT 0,expires_at TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE coupon_usage(id INTEGER PRIMARY KEY AUTOINCREMENT,coupon_id INTEGER NOT NULL,user_id INTEGER,order_id INTEGER NOT NULL,used_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(coupon_id,user_id,order_id),FOREIGN KEY(coupon_id) REFERENCES coupons(id),FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE banners(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,subtitle TEXT,cta_text TEXT,cta_url TEXT,desktop_url TEXT,mobile_url TEXT,video_url TEXT,start_at TEXT,end_at TEXT,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE homepage_sections(id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,title TEXT,subtitle TEXT,image_url TEXT,mobile_image_url TEXT,cta_text TEXT,cta_url TEXT,product_ids TEXT,enabled INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'published');
CREATE TABLE announcements(id INTEGER PRIMARY KEY AUTOINCREMENT,text TEXT NOT NULL,link TEXT,cta TEXT,enabled INTEGER NOT NULL DEFAULT 1,start_at TEXT,end_at TEXT,priority INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,title TEXT NOT NULL,body TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE reseller_profiles(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'pending',discount_percent INTEGER NOT NULL DEFAULT 0,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE activity_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,staff_user_id INTEGER,action TEXT NOT NULL,entity TEXT,entity_id TEXT,previous_value TEXT,new_value TEXT,ip TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(staff_user_id) REFERENCES users(id));

CREATE INDEX idx_products_active ON products(active);
CREATE INDEX idx_products_category ON products(category_id);
CREATE INDEX idx_orders_user ON orders(user_id);
CREATE INDEX idx_orders_status ON orders(status);
CREATE INDEX idx_reviews_product_status ON reviews(product_id,status);
CREATE INDEX idx_sessions_token ON sessions(token_hash);
CREATE INDEX idx_product_images_product ON product_images(product_id,sort_order);

